    @classmethod
    def _record(
        cls,
        metadata: dict[str, Any],
        name: str,
        expected: Any,
        observed: Any,
        passed: bool,
        failure_reason: str,
        *,
        diagnostic: bool = False,
    ) -> None:
        entry = {
            "check": name,
            "expected": expected,
            "observed": observed,
            "pass": bool(passed),
        }
        if diagnostic:
            entry["diagnostic"] = True
        metadata.setdefault("checks", []).append(entry)
        if not passed and not diagnostic:
            metadata.setdefault("failure_reasons", []).append(f"{name}: {failure_reason}")

    @classmethod
    def _numbers_equal(cls, actual: Any, expected: Any) -> bool:
        try:
            return math.isclose(
                float(actual),
                float(expected),
                rel_tol=0.0,
                abs_tol=cls.FLOAT_ABS_TOLERANCE,
            )
        except (TypeError, ValueError):
            return str(actual) == str(expected)

    @classmethod
    def _field_matches(cls, actual: Any, expected: Any) -> bool:
        """Compare an API field with an expectation, tolerating float noise."""

        if isinstance(expected, str) or isinstance(actual, str):
            return str(actual).strip().casefold() == str(expected).strip().casefold()
        if isinstance(expected, (int, float)) or isinstance(actual, (int, float)):
            return cls._numbers_equal(actual, expected)
        return str(actual) == str(expected)

    @classmethod
    def _read_api_state(cls, controller: Any, *, port: int, timeout_seconds: int) -> dict[str, Any]:
        code = dedent(
            f"""
            import json
            import urllib.request

            BASE_URL = "http://127.0.0.1:{port}"
            TIMEOUT = {timeout_seconds}

            def get_json(path):
                # A signed-out session answers 401 LOGIN_REQUIRED on /api/cart and
                # /api/orders.  Capture the HTTP status as observed state so the
                # check can fail on the missing data rather than aborting the read.
                # NOTE: this block lives inside an f-string, so literal braces are
                # doubled.
                import urllib.error
                try:
                    with urllib.request.urlopen(BASE_URL + path, timeout=TIMEOUT) as response:
                        return json.loads(response.read().decode("utf-8"))
                except urllib.error.HTTPError as exc:
                    body = exc.read().decode("utf-8", errors="replace")
                    try:
                        parsed = json.loads(body)
                    except Exception:
                        parsed = body[:1000]
                    return {{"__http_error__": {{"status": exc.code, "body": parsed}}}}
                except Exception as exc:  # noqa: BLE001 - surfaced, not swallowed
                    return {{"__http_error__": {{"status": None, "body": f"{{type(exc).__name__}}: {{exc}}"}}}}

            payload = {{
                "session": get_json("/api/session"),
                "cart": get_json("/api/cart"),
                "orders": get_json("/api/orders"),
                "benchmark": get_json("/api/benchmark"),
            }}
            print(json.dumps(payload, ensure_ascii=False))
            """
        ).strip()
        result = controller.run_python_script(code, timeout=timeout_seconds + 10)
        returncode = int(result.get("returncode", -1))
        output = str(result.get("stdout") or result.get("output") or "").strip()
        error = str(result.get("stderr") or result.get("error") or "").strip()
        if returncode != 0:
            detail = output or error or f"guest command failed with exit code {returncode}"
            raise RuntimeError(detail)
        try:
            payload = json.loads(output.splitlines()[-1])
        except (IndexError, json.JSONDecodeError) as exc:
            raise RuntimeError(f"guest API state was not valid JSON: {output}") from exc
        if not isinstance(payload, dict):
            raise RuntimeError("guest API state must be a JSON object")
        return payload

