    @classmethod
    def _check_orders(
        cls,
        expectation: Any,
        payload: Mapping[str, Any],
        metadata: dict[str, Any],
    ) -> None:
        if not isinstance(expectation, Mapping):
            return
        orders = list((payload or {}).get("orders") or [])
        if "count" in expectation:
            expected_count = int(expectation.get("count") or 0)
            actual_count = len(orders)
            cls._record(
                metadata,
                "orders.count",
                expected_count,
                actual_count,
                actual_count == expected_count,
                f"expected {expected_count} orders, observed {actual_count}",
            )

        recent = expectation.get("recent")
        if isinstance(recent, list):
            cls._check_recent_orders(
                recent,
                orders,
                metadata,
                in_order=bool(expectation.get("recent_in_order", False)),
            )
        elif isinstance(expectation.get("latest"), Mapping):
            latest = dict(expectation["latest"])
            if not orders:
                cls._record(
                    metadata,
                    "orders.latest",
                    "at least one order",
                    "none",
                    False,
                    "expected at least one order, observed none",
                )
            else:
                cls._validate_order(latest, orders[0], metadata, order_label="latest")

        for expected_order in expectation.get("by_id") or []:
            if not isinstance(expected_order, Mapping):
                continue
            order_id = str(expected_order.get("order_id") or expected_order.get("orderId") or "")
            if not order_id:
                cls._record(
                    metadata,
                    "orders.by_id",
                    "order_id present",
                    "missing",
                    False,
                    "orders.by_id entry is missing order_id",
                )
                continue
            order_match = next(
                (order for order in orders if str((order or {}).get("id") or "") == order_id),
                None,
            )
            cls._record(
                metadata,
                f"orders.by_id.{order_id}",
                "order present",
                order_id if order_match is not None else "none",
                order_match is not None,
                f"expected order id={order_id}, observed none",
            )
            if order_match is None:
                continue
            cls._validate_order(expected_order, order_match, metadata, order_label=f"order {order_id}")

    MAX_UNORDERED_RECENT = 6

    @classmethod
    def _check_recent_orders(
        cls,
        recent: list[Any],
        orders: list[Any],
        metadata: dict[str, Any],
        *,
        in_order: bool,
    ) -> None:
        """Match the ``recent`` expectations to the newest orders.

        ``/api/orders`` lists orders newest first.  The two-order briefs call
        the new orders "the first order" and "the second order" without saying
        which must be placed first; those are record labels, not chronology.
        So by default each expectation is matched to a distinct order among the
        newest ``len(recent)`` orders (the assignment with the fewest failed
        checks wins; ties keep the newest-first mapping), while
        ``orders.count`` still pins how many orders exist.  ``recent_in_order``
        restores the positional newest-first mapping.
        """

        indexed = [
            (index, dict(item)) for index, item in enumerate(recent) if isinstance(item, Mapping)
        ]
        size = len(recent)
        assignment: dict[int, int] = {index: index for index, _ in indexed}
        if not in_order and len(indexed) > 1 and size <= cls.MAX_UNORDERED_RECENT:
            best_failures: int | None = None
            for permutation in itertools.permutations(range(size), size):
                failures = 0
                for index, order_expectation in indexed:
                    position = permutation[index]
                    if position >= len(orders):
                        failures += 1
                        continue
                    scratch: dict[str, Any] = {"checks": [], "failure_reasons": []}
                    cls._validate_order(
                        order_expectation, orders[position], scratch, order_label="candidate"
                    )
                    failures += len(scratch["failure_reasons"])
                    if best_failures is not None and failures >= best_failures:
                        break
                if best_failures is None or failures < best_failures:
                    best_failures = failures
                    assignment = {index: permutation[index] for index, _ in indexed}
                if best_failures == 0:
                    break

        matched: dict[str, Any] = {}
        for index, order_expectation in indexed:
            position = assignment[index]
            label = str(order_expectation.get("label") or f"recent[{index}]")
            if position >= len(orders):
                cls._record(
                    metadata,
                    f"orders.recent[{position}]",
                    "order present",
                    "none",
                    False,
                    f"expected recent order {label!r} among the newest {size} orders, observed no order",
                )
                continue
            order = dict(orders[position] or {})
            matched[label] = {"position": position, "order_id": str(order.get("id") or "")}
            cls._validate_order(
                order_expectation,
                order,
                metadata,
                order_label=f"recent[{position}] ({label})",
            )
        metadata["recent_order_assignment"] = {
            "mode": "positional" if in_order else "unordered",
            "orders": matched,
        }

    @classmethod
    def _validate_order(
        cls,
        expectation: Mapping[str, Any],
        order: Any,
        metadata: dict[str, Any],
        *,
        order_label: str,
    ) -> None:
        order = dict(order or {})
        items = list(order.get("items") or [])
        string_fields = {
            "status": lambda o: str(o.get("status") or ""),
            "note": lambda o: str(o.get("note") or ""),
            "address_label": lambda o: str((o.get("address") or {}).get("label") or ""),
            "address_receiver": lambda o: str((o.get("address") or {}).get("receiver") or ""),
            "address_full": lambda o: str((o.get("address") or {}).get("fullAddress") or ""),
            "payment_id": lambda o: str((o.get("payment") or {}).get("id") or ""),
            "payment_label": lambda o: str((o.get("payment") or {}).get("label") or ""),
            "payment_desc": lambda o: str((o.get("payment") or {}).get("desc") or ""),
        }
        for key, reader in string_fields.items():
            if key not in expectation:
                continue
            expected = expectation[key]
            actual = reader(order)
            cls._record(
                metadata,
                f"{order_label}.{key}",
                expected,
                actual,
                cls._field_matches(actual, expected),
                f"expected {order_label} {key}={expected!r}, observed {actual!r}",
            )
        if "total" in expectation:
            expected_total = float(expectation.get("total") or 0)
            actual_total = float(order.get("total") or 0)
            cls._record(
                metadata,
                f"{order_label}.total",
                expected_total,
                actual_total,
                cls._numbers_equal(actual_total, expected_total),
                f"expected {order_label} total={expected_total}, observed {actual_total}",
            )
        if "item_count" in expectation:
            expected_count = int(expectation.get("item_count") or 0)
            actual_count = len(items)
            cls._record(
                metadata,
                f"{order_label}.item_count",
                expected_count,
                actual_count,
                actual_count == expected_count,
                f"expected {order_label} item_count={expected_count}, observed {actual_count}",
            )
        for expected_item in expectation.get("items") or []:
            if not isinstance(expected_item, Mapping):
                continue
            product_id = str(expected_item.get("product_id") or expected_item.get("productId") or "")
            item_match = next(
                (
                    item
                    for item in items
                    if str(((item.get("product") or {}).get("id") or "")) == product_id
                ),
                None,
            )
            cls._record(
                metadata,
                f"{order_label}.item.{product_id}",
                "item present",
                product_id if item_match is not None else "none",
                item_match is not None,
                f"expected {order_label} item with product_id={product_id}, observed none",
            )
            if item_match is None:
                continue
            cls._validate_order_item(
                expected_item,
                item_match,
                metadata,
                order_label=order_label,
                product_id=product_id,
            )

    @classmethod
    def _validate_order_item(
        cls,
        expectation: Mapping[str, Any],
        item: Any,
        metadata: dict[str, Any],
        *,
        order_label: str,
        product_id: str,
    ) -> None:
        item = dict(item or {})
        if "quantity" in expectation:
            expected_quantity = int(expectation.get("quantity") or 0)
            actual_quantity = int(item.get("quantity") or 0)
            cls._record(
                metadata,
                f"{order_label}.item.{product_id}.quantity",
                expected_quantity,
                actual_quantity,
                actual_quantity == expected_quantity,
                f"expected {order_label} quantity {expected_quantity} for {product_id}, observed {actual_quantity}",
            )
        if "selected_spec" in expectation:
            expected_spec = str(expectation.get("selected_spec") or "")
            actual_spec = str(item.get("selectedSpec") or "")
            cls._record(
                metadata,
                f"{order_label}.item.{product_id}.selected_spec",
                expected_spec,
                actual_spec,
                actual_spec == expected_spec,
                f"expected {order_label} selectedSpec={expected_spec!r} for {product_id}, observed {actual_spec!r}",
            )

        actual_review = item.get("review")
        if bool(expectation.get("review_absent", False)):
            cls._record(
                metadata,
                f"{order_label}.item.{product_id}.review_absent",
                True,
                not isinstance(actual_review, Mapping),
                not isinstance(actual_review, Mapping),
                f"expected {order_label} product {product_id} to have no submitted review",
            )
            return
        review_expectation = expectation.get("review")
        if not isinstance(review_expectation, Mapping):
            return
        if not isinstance(actual_review, Mapping):
            cls._record(
                metadata,
                f"{order_label}.item.{product_id}.review",
                "review present",
                "none",
                False,
                f"expected {order_label} product {product_id} to have a review, observed none",
            )
            return
        if "rating" in review_expectation:
            expected_rating = int(review_expectation.get("rating") or 0)
            actual_rating = int(actual_review.get("rating") or 0)
            cls._record(
                metadata,
                f"{order_label}.item.{product_id}.review.rating",
                expected_rating,
                actual_rating,
                actual_rating == expected_rating,
                f"expected {order_label} product {product_id} review rating={expected_rating}, observed {actual_rating}",
            )
        if "text" in review_expectation:
            expected_text = str(review_expectation.get("text") or "")
            accepted = cls._accepted_texts(expected_text, review_expectation.get("text_variants"))
            actual_text = str(actual_review.get("review") or actual_review.get("text") or "")
            cls._record(
                metadata,
                f"{order_label}.item.{product_id}.review.text",
                expected_text if len(accepted) == 1 else list(accepted),
                actual_text,
                actual_text.strip() in {text.strip() for text in accepted},
                f"expected {order_label} product {product_id} review text in {list(accepted)!r}, observed {actual_text!r}",
            )

    @staticmethod
    def _accepted_texts(text: str, variants: Any) -> tuple[str, ...]:
        """The exact text plus the exact variants a task also accepts.

        Some briefs quote a review with the sentence punctuation inside the
        closing quote (“Good to share,”), so a reader cannot tell whether the
        mark belongs to the text; such a task lists the other reading as a
        variant.  Every accepted text is still compared exactly (after strip).
        """

        accepted = [text]
        if isinstance(variants, (list, tuple)):
            accepted.extend(str(item) for item in variants if str(item or ""))
        return tuple(dict.fromkeys(accepted))

    @classmethod
    def _check_benchmark(
        cls,
        expectation: Any,
        payload: Mapping[str, Any],
        metadata: dict[str, Any],
    ) -> None:
        if not isinstance(expectation, Mapping):
            return
        events = list((payload or {}).get("events") or [])
        ordered = expectation.get("ordered")
        if isinstance(ordered, list):
            cls._check_ordered_ledger(expectation, ordered, events, metadata)
        cls._check_required_events(expectation.get("required_events"), events, metadata)
        cls._check_event_precedence(expectation.get("precedence"), events, metadata)

    @classmethod
    def _event_matches(
        cls,
        event: Any,
        expected_event: Mapping[str, Any],
        metadata: Mapping[str, Any],
    ) -> bool:
        if not isinstance(event, Mapping):
            return False
        event_type = str(expected_event.get("type") or "").strip()
        if str(event.get("type") or "") != event_type:
            return False
        for key, value in expected_event.items():
            if key in {"type", "label"}:
                continue
            if key == "order_label":
                assigned = ((metadata.get("recent_order_assignment") or {}).get("orders") or {}).get(
                    str(value)
                )
                order_id = str((assigned or {}).get("order_id") or "")
                if not order_id or str(event.get("orderId") or "") != order_id:
                    return False
                continue
            if not cls._field_matches(event.get(key), value):
                return False
        return True

    @classmethod
    def _check_required_events(
        cls,
        required: Any,
        events: list[Any],
        metadata: dict[str, Any],
    ) -> None:
        """Events the brief asks for as deliverables: at least once, anywhere."""

        if not isinstance(required, list):
            return
        for position, expected_event in enumerate(required):
            if not isinstance(expected_event, Mapping):
                continue
            label = str(expected_event.get("label") or f"required_events[{position}]")
            matches = [
                index
                for index, event in enumerate(events)
                if cls._event_matches(event, expected_event, metadata)
            ]
            cls._record(
                metadata,
                f"benchmark.required_event.{label}",
                {key: value for key, value in expected_event.items() if key != "label"},
                {"match_count": len(matches), "event_indices": matches},
                bool(matches),
                f"expected at least one benchmark event matching {dict(expected_event)}, observed none",
            )

    @classmethod
    def _check_event_precedence(
        cls,
        pairs: Any,
        events: list[Any],
        metadata: dict[str, Any],
    ) -> None:
        """Brief-stated pairwise orders: some ``after`` match follows a ``before`` match.

        Only orders the brief states with temporal language ("followed by",
        "replacing an initial ...") are listed; the latest matching ``after``
        event (the one that produced the final state) must come after the first
        matching ``before`` event.
        """

        if not isinstance(pairs, list):
            return
        for position, pair in enumerate(pairs):
            if not isinstance(pair, Mapping):
                continue
            label = str(pair.get("label") or f"precedence[{position}]")
            before = pair.get("before") if isinstance(pair.get("before"), Mapping) else {}
            after = pair.get("after") if isinstance(pair.get("after"), Mapping) else {}
            before_indices = [
                index for index, event in enumerate(events) if cls._event_matches(event, before, metadata)
            ]
            after_indices = [
                index for index, event in enumerate(events) if cls._event_matches(event, after, metadata)
            ]
            passed = bool(before_indices and after_indices and max(after_indices) > min(before_indices))
            if not before_indices:
                reason = f"no benchmark event matches the earlier step {dict(before)}"
            elif not after_indices:
                reason = f"no benchmark event matches the later step {dict(after)}"
            else:
                reason = (
                    f"the later step {dict(after)} (events {after_indices}) never follows "
                    f"the earlier step {dict(before)} (events {before_indices})"
                )
            cls._record(
                metadata,
                f"benchmark.precedence.{label}",
                {"before": dict(before), "after": dict(after)},
                {"before_indices": before_indices, "after_indices": after_indices},
                passed,
                reason,
            )

    @classmethod
    def _check_ordered_ledger(
        cls,
        expectation: Mapping[str, Any],
        ordered: list[Any],
        events: list[Any],
        metadata: dict[str, Any],
    ) -> None:
        # Restored benchmark instrumentation: the recorded demo's whole ledger,
        # including searches, product views and the order of the orders and
        # reviews.  The English briefs never state that order (scan.CSV MAC-037 /
        # MAC-040, class step_gate), so the ledger is diagnostic unless a task
        # explicitly opts in; orders the brief does state live in
        # ``benchmark.precedence`` and searches it asks for in
        # ``benchmark.required_events``.
        require_ordered = bool(expectation.get("require_ordered", False))
        prefix = "benchmark.ordered" if require_ordered else "benchmark.ordered.diagnostic"
        matched_all = True
        cursor = 0
        for position, expected_event in enumerate(ordered):
            if not isinstance(expected_event, Mapping):
                continue
            event_type = str(expected_event.get("type") or "").strip()
            if not event_type:
                cls._record(
                    metadata,
                    f"{prefix}[{position}]",
                    "type present",
                    "missing",
                    False,
                    "benchmark event expectation is missing type",
                    diagnostic=not require_ordered,
                )
                matched_all = False
                continue
            matcher = {key: value for key, value in expected_event.items() if key != "type"}
            found_at: int | None = None
            for index in range(cursor, len(events)):
                event = dict(events[index] or {})
                if str(event.get("type") or "") != event_type:
                    continue
                if all(cls._field_matches(event.get(key), value) for key, value in matcher.items()):
                    found_at = index
                    break
            cls._record(
                metadata,
                f"{prefix}[{position}]",
                {"type": event_type, **matcher},
                found_at if found_at is not None else "no matching event",
                found_at is not None,
                f"expected ordered benchmark event {event_type} with {matcher}, observed none after cursor {cursor}",
                diagnostic=not require_ordered,
            )
            if found_at is not None:
                cursor = found_at + 1
            else:
                matched_all = False
        if not require_ordered:
            metadata.setdefault("diagnostics", []).append(
                {
                    "diagnostic_id": "benchmark.ordered",
                    "passed": matched_all,
                    "blocking": False,
                    "note": (
                        "The recorded demo ledger's order is not stated in the brief; PASS/FAIL "
                        "comes from the durable session/cart/order/review state plus any "
                        "benchmark.required_events and benchmark.precedence checks."
                    ),
                }
            )

    @classmethod
    def _check_ui(
        cls,
        controller: Any,
        context: Mapping[str, Any],
        expectation: Any,
        metadata: dict[str, Any],
    ) -> None:
        if not isinstance(expectation, Mapping):
            return
        observation = context.get("final_observation")
        try:
            if observation is None:
                observation = controller.observe(
                    include_ui_tree=True,
                    include_screenshot_data=False,
                )
            foreground_app = str(cls._observation_field(observation, "foreground_app") or "")
            foreground_bundle_id = str(
                cls._observation_field(observation, "foreground_bundle_id") or ""
            )
            raw_nodes = cls._observation_field(observation, "ui_nodes", []) or []
            ui_nodes = [node for node in raw_nodes if isinstance(node, Mapping)]
        except Exception as exc:
            cls._record(
                metadata,
                "ui.foreground",
                "observable foreground",
                "observation failed",
                False,
                f"UI observation failed: {type(exc).__name__}: {exc}",
            )
            return
        observed = {
            "foreground_app": foreground_app,
            "foreground_bundle_id": foreground_bundle_id,
            "ui_node_count": len(ui_nodes),
        }
        metadata["observed_state"]["ui"] = observed
        if not expectation.get("require_foreground", False):
            return
        app_names = [str(name).strip() for name in (expectation.get("app_names") or []) if str(name).strip()]
        bundle_ids = [str(bid).strip() for bid in (expectation.get("bundle_ids") or []) if str(bid).strip()]
        app_ok = any(name.casefold() in foreground_app.casefold() for name in app_names)
        bundle_ok = any(
            foreground_bundle_id.casefold() == bundle_id.casefold() for bundle_id in bundle_ids
        )
        cls._record(
            metadata,
            "ui.foreground",
            {"app_names": app_names, "bundle_ids": bundle_ids},
            observed,
            bool(app_ok or bundle_ok),
            f"expected OpenShop foreground, observed app={foreground_app!r}, bundle={foreground_bundle_id!r}",
        )


